import pytest

from sqllineage.core.metadata_provider import MetaDataProvider
from sqllineage.utils.entities import ColumnQualifierTuple
from ...helpers import assert_column_lineage_equal, generate_metadata_providers


providers = generate_metadata_providers(
    {
        "db.source": ["user_id", "user_name"],
        "db.target": ["id", "name"],
    }
)


@pytest.mark.parametrize("provider", providers)
def test_insert_select_uses_target_columns_from_metadata(provider: MetaDataProvider):
    sql = """insert into db.target
    select user_id, user_name
    from db.source
    """
    assert_column_lineage_equal(
        sql,
        [
            (
                ColumnQualifierTuple("user_id", "db.source"),
                ColumnQualifierTuple("id", "db.target"),
            ),
            (
                ColumnQualifierTuple("user_name", "db.source"),
                ColumnQualifierTuple("name", "db.target"),
            ),
        ],
        metadata_provider=provider,
    )
